namespace sv_792fbeea92904afebac8bd6dae48959c.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
    min-height: 100%;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s, border-color 0.15s;
    font-size: 0.95rem;
}

.settings-sidebar li:hover {
    background: #e9ecef;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    border-left-color: #1976d2;
    font-weight: 600;
    color: #1976d2;
}

.sidebar-icon {
    font-size: 1.1rem;
}

@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@editAvatarUrl" alt="Avatar" class="avatar-img" />
                <p class="avatar-url-label">Avatar URL:</p>
                <code class="avatar-url">@editAvatarUrl</code>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editAvatarUrl = profile.AvatarUrl;
        editBio = profile.Bio;
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        showSuccess = false;
        errorMessage = null;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
            await SettingsService.SaveProfileAsync(updated);
            savedProfile = updated;
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}

@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                @if (allChannels.Count == 0)
                {
                    <p class="muted-text">No channels available.</p>
                }
                else
                {
                    <ul class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <li>
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@mutedChannels.Contains(channel)"
                                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            </li>
                        }
                    </ul>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        // Expose all known channels (muted ones are the list we know about)
        allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        showSuccess = true;
        isSaving = false;
    }
}

@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    @if (passwordError is not null)
                    {
                        <div class="toast error">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "●" : "○")
                </span>
                <span>@(twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-row">
                    <input type="checkbox" @bind="twoFactorEnabled" class="toggle-switch" />
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="muted-text">Last password change: @lastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (sessions.Count == 0)
            {
                <p class="muted-text">No active sessions.</p>
            }
            else
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation>
