@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (isLoading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@editAvatarUrl" alt="Avatar" class="avatar-img" />
                <p class="avatar-url-label">Avatar URL:</p>
                <code class="avatar-url">@editAvatarUrl</code>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
            @if (errorMessage is not null)
            {
                <div class="toast error">@errorMessage</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;
    private string? errorMessage;

    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editAvatarUrl = "";
    private string editBio = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editAvatarUrl = profile.AvatarUrl;
        editBio = profile.Bio;
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
        }
        showSuccess = false;
        errorMessage = null;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;
        errorMessage = null;

        try
        {
            var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
            await SettingsService.SaveProfileAsync(updated);
            savedProfile = updated;
            showSuccess = true;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}
"}

{"path": "/tmp/sv-792fbeea92904afebac8bd6dae48959c/Components/Pages/Settings/NotificationsSection.razor", "file_text": "@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                @if (allChannels.Count == 0)
                {
                    <p class="muted-text">No channels available.</p>
                }
                else
                {
                    <ul class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <li>
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@mutedChannels.Contains(channel)"
                                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            </li>
                        }
                    </ul>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        // Expose all known channels (muted ones are the list we know about)
        allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        showSuccess = true;
        isSaving = false;
    }
}
"}

{"path": "/tmp/sv-792fbeea92904afebac8bd6dae48959c/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    @if (passwordError is not null)
                    {
                        <div class="toast error">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "●" : "○")
                </span>
                <span>@(twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-row">
                    <input type="checkbox" @bind="twoFactorEnabled" class="toggle-switch" />
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="muted-text">Last password change: @lastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (sessions.Count == 0)
            {
                <p class="muted-text">No active sessions.</p>
            }
            else
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation>
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool passwordPanelOpen;
    private bool isChangingPassword;
    private bool passwordSuccess;
    private string? passwordError;

    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";

    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;

    // Assume first session is current
    private string currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions;
        currentSessionId = sessions.FirstOrDefault()?.Id ?? "";
        isLoading = false;
    }

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password cannot be empty.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        sessions.Remove(sessionToRevoke);
        sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-792fbeea92904afebac8bd6dae48959c/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme -->
            <fieldset class="form-group">
                <legend>Theme</legend>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </fieldset>

            <!-- Font Size -->
            <fieldset class="form-group">
                <legend>Font Size</legend>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </fieldset>

            <!-- Language -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <label class="toggle-row">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            </label>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A brief description of an item in your dashboard.</p>
                    <button class="preview-btn">Action</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        selectedTheme = settings.Theme;
        selectedFontSize = settings.FontSize;
        selectedLanguage = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = selectedTheme.ToLowerInvariant();
        var size = selectedFontSize.ToLowerInvariant();
        var compact = compactMode ? "compact" : "";
        return $"preview-{theme} preview-{size} {compact}".Trim();
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        showSuccess = true;
        isSaving = false;
    }
}
"}

