@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (isLoading)
    {
        <p class="loading">Loading notification preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-row">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="emailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="pushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-row">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="weeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <div class="channels-section">
                <h3>Muted Channels</h3>
                @if (allChannels.Count == 0)
                {
                    <p class="muted-text">No channels available.</p>
                }
                else
                {
                    <ul class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <li>
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@mutedChannels.Contains(channel)"
                                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                                    <span>@channel</span>
                                </label>
                            </li>
                        }
                    </ul>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private List<string> allChannels = new();

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        // Expose all known channels (muted ones are the list we know about)
        allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        showSuccess = true;
        isSaving = false;
    }
}

