<div class="settings-section">
    <h2>Security</h2>

    @if (isLoading)
    {
        <p class="loading">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    @if (passwordError is not null)
                    {
                        <div class="toast error">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn-primary" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @(isChangingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h3>Two-Factor Authentication</h3>
            <div class="tfa-status">
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "●" : "○")
                </span>
                <span>@(twoFactorEnabled ? "Enabled" : "Disabled")</span>
                <label class="toggle-row">
                    <input type="checkbox" @bind="twoFactorEnabled" class="toggle-switch" />
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="muted-text">Last password change: @lastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            @if (sessions.Count == 0)
            {
                <p class="muted-text">No active sessions.</p>
            }
            else
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("g")</td>
                                <td>
                                    @if (session.Id != currentSessionId)
                                    {
                                        <button class="btn-danger btn-sm" @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                    else
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation>
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool passwordPanelOpen;
    private bool isChangingPassword;
    private bool passwordSuccess;
    private string? passwordError;

    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";

    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;

    // Assume first session is current
    private string currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions;
        currentSessionId = sessions.FirstOrDefault()?.Id ?? "";
        isLoading = false;
    }

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "New password cannot be empty.";
            return;
        }

        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        isChangingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            passwordSuccess = true;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            passwordError = ex.Message;
        }
        finally
        {
            isChangingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
        sessions.Remove(sessionToRevoke);
        sessionToRevoke = null;
    }
}

