@namespace sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@using sv_792fbeea92904afebac8bd6dae48959c.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (isLoading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme -->
            <fieldset class="form-group">
                <legend>Theme</legend>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </fieldset>

            <!-- Font Size -->
            <fieldset class="form-group">
                <legend>Font Size</legend>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </fieldset>

            <!-- Language -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="selectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <label class="toggle-row">
                <span>Compact Mode</span>
                <input type="checkbox" @bind="compactMode" class="toggle-switch" />
            </label>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <div class="preview-card">
                    <strong>Sample Card</strong>
                    <p>A brief description of an item in your dashboard.</p>
                    <button class="preview-btn">Action</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @(isSaving ? "Saving..." : "Save")
                </button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool isLoading = true;
    private bool isSaving;
    private bool showSuccess;

    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        selectedTheme = settings.Theme;
        selectedFontSize = settings.FontSize;
        selectedLanguage = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = selectedTheme.ToLowerInvariant();
        var size = selectedFontSize.ToLowerInvariant();
        var compact = compactMode ? "compact" : "";
        return $"preview-{theme} preview-{size} {compact}".Trim();
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        showSuccess = true;
        isSaving = false;
    }
}

