namespace sv_792fbeea92904afebac8bd6dae48959c.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_792fbeea92904afebac8bd6dae48959c.Services
@using sv_792fbeea92904afebac8bd6dae48959c.Components.Pages.Settings
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
    margin: 1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

/* Shared section styles */
::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #1a1a1a;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label,
::deep .form-group legend {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    font-size: 0.9rem;
    color: #333;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .form-group textarea {
    resize: vertical;
}

::deep .button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

::deep .btn-primary {
    background: #1976d2;
    color: #fff;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

::deep .btn-primary:hover:not(:disabled) {
    background: #1565c0;
}

::deep .btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-secondary {
    background: #fff;
    color: #333;
    border: 1px solid #ccc;
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-secondary:hover {
    background: #f5f5f5;
}

::deep .btn-danger {
    background: #d32f2f;
    color: #fff;
    border: none;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

::deep .btn-danger:hover {
    background: #b71c1c;
}

::deep .btn-sm {
    padding: 0.3rem 0.6rem;
    font-size: 0.8rem;
}

::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .toast.success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

::deep .toast.error {
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

::deep .toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0;
    max-width: 400px;
    cursor: pointer;
}

::deep .toggle-switch {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

::deep .loading {
    color: #666;
    font-style: italic;
}

::deep .muted-text {
    color: #666;
    font-size: 0.85rem;
}

/* Profile avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
}

::deep .avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e0e0e0;
    background: #f0f0f0;
}

::deep .avatar-url-label {
    margin: 0.5rem 0 0.2rem;
    font-size: 0.8rem;
    color: #666;
}

::deep .avatar-url {
    font-size: 0.8rem;
    word-break: break-all;
    color: #555;
}

/* Notifications channels */
::deep .channels-section {
    margin-top: 1.5rem;
}

::deep .channel-list {
    list-style: none;
    padding: 0;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

/* Security panel */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

::deep .tfa-section {
    margin-bottom: 1.5rem;
}

::deep .tfa-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .status-indicator {
    font-size: 1.2rem;
}

::deep .status-indicator.enabled {
    color: #2e7d32;
}

::deep .status-indicator.disabled {
    color: #999;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e0e0e0;
    font-size: 0.9rem;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
}

::deep .current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1976d2;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
}

/* Dialog */
::deep .dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

::deep .dialog h4 {
    margin-top: 0;
}

::deep .dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
}

/* Appearance preview */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    transition: all 0.2s;
}

::deep .preview-area.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

::deep .preview-area.preview-light {
    background: #fff;
    color: #333;
}

::deep .preview-area.preview-system {
    background: #f9f9f9;
    color: #333;
}

::deep .preview-area.preview-small {
    font-size: 0.8rem;
}

::deep .preview-area.preview-medium {
    font-size: 1rem;
}

::deep .preview-area.preview-large {
    font-size: 1.2rem;
}

::deep .preview-area.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

::deep .preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid currentColor;
    border-radius: 4px;
    opacity: 0.8;
}

::deep .preview-btn {
    margin-top: 0.5rem;
    padding: 0.4rem 0.8rem;
    background: #1976d2;
    color: #fff;
    border: none;
    border-radius: 3px;
    cursor: default;
    font-size: inherit;
}

/* Radio groups */
::deep .radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

::deep .radio-item {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
}

::deep fieldset.form-group {
    border: none;
    padding: 0;
    margin: 0 0 1rem;
}

::deep fieldset.form-group legend {
    font-weight: 600;
    margin-bottom: 0.35rem;
    font-size: 0.9rem;
    color: #333;
}

